from __future__ import annotations

from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]


def stub_translate(
    cues: list[dict[str, Any]],
    *,
    mt_model: str = "opus-mt-en-zh",
    on_progress: ProgressCb | None = None,
) -> list[dict[str, Any]]:
    if on_progress:
        on_progress({"stage": "translate", "percent": 50, "detail": f"桩 · 翻译 {mt_model}"})
    out: list[dict[str, Any]] = []
    for cue in cues:
        text = str(cue.get("text") or "")
        out.append(
            {
                "start": cue.get("start"),
                "end": cue.get("end"),
                "text": f"[zh] {text}",
            }
        )
    if on_progress:
        on_progress({"stage": "translate", "percent": 95, "detail": f"{len(out)} 条"})
    return out
